/// Vertex format flags determining vertex buffer layout
///
/// These bitmask flags control the per-vertex data layout in the U8__ vertex blob. The vertex stride is: 24 + (hasColor ? 4 : 0) + (numUVs * 4) + 4 bytes.
/// Bit flags. Combine with `|`, test with [`VertexFormatFlag::contains`].
#[derive(Clone, Copy, PartialEq, Eq, Hash, Default)]
pub struct VertexFormatFlag(pub i32);

impl VertexFormatFlag {
    pub const NONE: Self = Self(0);
    /// Bit 10 (1-based): Has vertex color (adds 4 bytes)
    pub const VERTEX_COLOR: Self = Self(512);
    /// Bit 18 (1-based): Has UV layer 1 (adds 4 bytes)
    pub const UV_1: Self = Self(131072);
    /// Bit 19 (1-based): Has UV layer 2 (adds 4 bytes)
    pub const UV_2: Self = Self(262144);
    /// Bit 20 (1-based): Has UV layer 3 (adds 4 bytes)
    pub const UV_3: Self = Self(524288);
    /// Bit 21 (1-based): Has UV layer 4 (adds 4 bytes)
    pub const UV_4: Self = Self(1048576);
    /// Bit 30 (1-based): Has UV layer 5 (adds 4 bytes)
    pub const UV_5: Self = Self(536870912);

    #[inline]
    pub const fn contains(self, other: Self) -> bool {
        (self.0 & other.0) == other.0
    }

    #[inline]
    pub const fn is_empty(self) -> bool {
        self.0 == 0
    }
}

impl core::ops::BitOr for VertexFormatFlag {
    type Output = Self;
    #[inline]
    fn bitor(self, rhs: Self) -> Self {
        Self(self.0 | rhs.0)
    }
}

impl core::ops::BitAnd for VertexFormatFlag {
    type Output = Self;
    #[inline]
    fn bitand(self, rhs: Self) -> Self {
        Self(self.0 & rhs.0)
    }
}

impl core::ops::Not for VertexFormatFlag {
    type Output = Self;
    #[inline]
    fn not(self) -> Self {
        Self(!self.0)
    }
}

impl core::fmt::Debug for VertexFormatFlag {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        write!(f, "VertexFormatFlag({:#x})", self.0)
    }
}

