// SAFETY: handles are plain heap pointers with no thread affinity. `Sync`
// is deliberately NOT implemented — the C++ types make no documented
// guarantee about concurrent use, and claiming one we haven't verified
// would be unsound. See `@bind thread_safe` in the plan.
unsafe impl Send for AnimationState {}

impl core::fmt::Debug for AnimationState {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.debug_struct("AnimationState").finish_non_exhaustive()
    }
}

impl AnimationState {
    /// # Panics
    /// Panics if the native allocation fails.
    pub fn new() -> Self {
        // SAFETY: the native constructor returns a live handle; a null here
        // means the library is unusable.
        unsafe {
            let raw = ffi::whiteout_m3_M3AnimationState_new();
            Self::from_raw(raw).expect("native AnimationState allocation failed")
        }
    }

    /// Animation IDs (U32_)
    /// Zero-copy view of the underlying `std::vector`.
    pub fn anim_ids(&self) -> &[u32] {
        // SAFETY: `_data`/`_count` describe one contiguous C++
        // allocation, borrowed for as long as `self` is.
        unsafe {
            let n = ffi::whiteout_m3_M3AnimationState_get_animIds_count(self.raw.as_ptr());
            let p = ffi::whiteout_m3_M3AnimationState_get_animIds_data(self.raw.as_ptr());
            if p.is_null() || n == 0 {
                &[]
            } else {
                core::slice::from_raw_parts(p, n)
            }
        }
    }

    /// Zero-copy mutable view. Resize first — the borrow forbids it after.
    pub fn anim_ids_mut(&mut self) -> &mut [u32] {
        // SAFETY: as above; `&mut self` rules out aliasing and resizing.
        unsafe {
            let n = ffi::whiteout_m3_M3AnimationState_get_animIds_count(self.raw.as_ptr());
            let p =
                ffi::whiteout_m3_M3AnimationState_get_animIds_data(self.raw.as_ptr()) as *mut u32;
            if p.is_null() || n == 0 {
                &mut []
            } else {
                core::slice::from_raw_parts_mut(p, n)
            }
        }
    }

    pub fn set_anim_ids(&mut self, values: &[u32]) {
        // SAFETY: the native side copies `values` before returning.
        unsafe {
            ffi::whiteout_m3_M3AnimationState_assign_animIds(
                self.raw.as_ptr(),
                values.as_ptr() as *const _,
                values.len(),
            )
        }
    }

    pub fn resize_anim_ids(&mut self, count: usize) {
        // SAFETY: reallocation is safe here precisely because
        // `&mut self` means no slice borrow is outstanding.
        unsafe { ffi::whiteout_m3_M3AnimationState_resize_animIds(self.raw.as_ptr(), count) }
    }

    /// Unknown state data (16 bytes)
    /// Number of elements — a fixed-size C++ array.
    pub const fn unknown_len() -> usize {
        16
    }

    /// # Panics
    /// If `index >= 16`, matching Rust slice indexing.
    pub fn unknown(&self, index: usize) -> u8 {
        assert!(index < 16, "unknown index {index} out of range (len 16)");
        // SAFETY: index checked above; plain scalar read.
        unsafe { ffi::whiteout_m3_M3AnimationState_get_unknown_at(self.raw.as_ptr(), index) }
    }

    /// # Panics
    /// If `index >= 16`.
    pub fn set_unknown(&mut self, index: usize, value: u8) {
        assert!(index < 16, "unknown index {index} out of range (len 16)");
        // SAFETY: index checked above.
        unsafe { ffi::whiteout_m3_M3AnimationState_set_unknown_at(self.raw.as_ptr(), index, value) }
    }
}

impl Default for AnimationState {
    fn default() -> Self {
        Self::new()
    }
}

